{
  "shared_conditions": [
    "The lubricant-change instruction concerns prolonged operation below -15°F (-26°C).",
    "The transmission-fluid recommendations concern arctic or extreme-cold conditions."
  ],
  "statements": [
    {
      "statement": "For prolonged operation below -15°F (-26°C), the general instruction is to change the transmission fluid more frequently.",
      "answer_quote": "the general lubricant-change instruction is to change the transmission fluid more frequently"
    },
    {
      "statement": "For prolonged operation below -15°F (-26°C), increased viscosity and potential degradation at low temperatures are given as reasons to change the transmission fluid more frequently.",
      "answer_quote": "due to increased viscosity and potential degradation at low temperatures"
    },
    {
      "statement": "In arctic conditions, the transmission PMCS notes specify a synthetic transmission fluid suitable for those conditions.",
      "answer_quote": "The transmission PMCS notes specify the use of a synthetic transmission fluid suitable for arctic conditions"
    },
    {
      "statement": "In arctic conditions, MIL-PRF-83133 or a high-performance synthetic fluid approved for cold environments is offered as an example of a suitable transmission fluid.",
      "answer_quote": "such as MIL-PRF-83133 or a high-performance synthetic fluid approved for use in cold environments"
    },
    {
      "statement": "In arctic conditions, the answer says the recommended transmission fluid includes Type 1 or Type 2 synthetic fluid, depending on the transmission model.",
      "answer_quote": "include Type 1 or Type 2 synthetic fluids, depending on transmission model"
    },
    {
      "statement": "In extreme cold, the answer says the recommended synthetic fluids ensure proper lubrication and performance.",
      "answer_quote": "to ensure proper lubrication and performance in extreme cold"
    }
  ],
  "excluded_metadata": [
    "The manual identifier and edition dates are source-provenance information: “TM 9-2320-280-20-1 (1996, including Change 2 dated 2004)”.",
    "Citation availability: “[No specific chunk IDs available in reference]”."
  ]
}

